import { loadFont } from "@remotion/google-fonts/BricolageGrotesque";
import { forwardRef, useEffect, useId, useImperativeHandle, useLayoutEffect, useMemo, useRef, type ComponentProps, type ReactNode } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, spring, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Chrome parks a glyph raster on a whole pixel vertically for as long as the
// matrix that carries it is axis-aligned, so text under a slow transform
// clicks along pixel by pixel. A lean too small to see takes it off that grid.
//
// A transform that carries text is marked, and told when it moves:
//
//   const glide = useGlide();
//   transform: `scale(${s})${glide(moving)}`
//
// The mark changes nothing by itself. After every frame the blocks of text
// under a marked transform get the lean: each about its own centre, and each
// by no more than its size on the screen needs. A card, a hairline or an image
// is fine under a transform as it is, so they stay level.
//
// Text leans while its transform moves, and it keeps the lean at rest when it
// rests off the pixel grid (a scene shown smaller in a player, a camera that
// holds at 1.03): dropping the lean there would snap it to the nearest pixel,
// up to half a pixel in one frame, and picking it up would snap it back. Text
// that rests on the grid loses the lean without moving, so a scene at rest at
// full size is drawn exactly as it would be without any of this.

/**
 * Returns `glide(moving)`: append it to a transform that carries text, with
 * `moving` true on the frames where that transform changes.
 *
 * Everything else lives inside this one closure: the build of Studio
 * elements pastes this file whole into the component that uses it, where a
 * second `LEAN` or `lean` at the top level would collide.
 */
const useGlide = (() => {
  /** What `glide(false)` adds to a transform: an identity matrix, to find it by. */
  const AT_REST = " matrix(1, 0, 0, 1, 0, 0)";
  /** `glide(true)` adds it twice. */
  const MOVING = AT_REST + AT_REST;
  const MARKED = `[style*="${AT_REST.trim()}"]`;
  // Text leaves the grid once the matrix leans x into y by half of 1/1024 in
  // device pixels (Skia rounds the glyph matrix to 1/1024). A fifth over it.
  const LEAN = 0.6 / 1024;
  // Past this the text is a speck on the screen; it is left alone.
  const STEEPEST = 5;
  // How far from a whole pixel text may rest and still count as on the grid:
  // the jump it makes when the lean goes is no bigger than this.
  const ON_GRID = 0.05;

  /** The linear part of a 2D matrix: x' = a·x + c·y, y' = b·x + d·y. */
  type Lin = [a: number, b: number, c: number, d: number];
  const LEVEL: Lin = [1, 0, 0, 1];
  const times = (m: Lin, n: Lin): Lin => [
    m[0] * n[0] + m[2] * n[1],
    m[1] * n[0] + m[3] * n[1],
    m[0] * n[2] + m[2] * n[3],
    m[1] * n[2] + m[3] * n[3],
  ];
  const turned = (degrees: number): Lin => {
    const t = (degrees * Math.PI) / 180;
    return [Math.cos(t), Math.sin(t), -Math.sin(t), Math.cos(t)];
  };
  const offWhole = (n: number) => Math.abs(n - Math.round(n));

  type Block = HTMLElement | SVGTextElement | SVGSVGElement;
  let leant: Block[] = [];
  // Fonts arrive after the first pass and change what is laid out where, with
  // no render to follow: a block or a marked element that changes size is read
  // again before the frame is painted.
  let watcher: ResizeObserver | undefined;
  const watched = new WeakSet<Element>();
  const watch = (el: Element) => {
    if (watched.has(el)) return;
    watched.add(el);
    watcher ??= new ResizeObserver(() => lean());
    watcher.observe(el);
  };

  const depthOf = (el: Element) => {
    let depth = 0;
    for (let up = el.parentElement; up; up = up.parentElement) depth += 1;
    return depth;
  };

  /** The nearest box around a text node that a transform applies to. */
  const blockOf = (node: Node): Block | null => {
    for (let el = node.parentElement; el; el = el.parentElement) {
      if (el instanceof SVGElement) {
        const text = el.closest("text");
        if (!(text instanceof SVGTextElement)) return null;
        // Text that only shapes a mask or a clip is not drawn where it stands
        // and cannot turn by itself: its whole drawing leans for it.
        if (!text.closest("defs, mask, clipPath, pattern, symbol, marker"))
          return text;
        let drawing = text.ownerSVGElement;
        while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
        return drawing;
      }
      if (!(el instanceof HTMLElement)) continue;
      const { display } = getComputedStyle(el);
      if (display !== "inline" && display !== "contents") return el;
    }
    return null;
  };

  /** One pass over the page: what every element's own transforms do. */
  function reader(given: Map<Element, number>) {
    type Own = {
      /** `scale` and `transform`, without the `rotate` property. */
      lin: Lin;
      /** `rotate`, in degrees: a lean given in this pass, or the scene's own. */
      turn: number;
      /** How far down it is moved, and by what whole factor it is scaled from
       * its top left corner; null when it does anything else. */
      carry: { dy: number; k: number } | null;
    };
    const lens = new Map<Element, boolean>();
    /** Whether an element shows its children in perspective. */
    const lensOn = (el: Element | null): boolean => {
      if (!el) return false;
      const seen = lens.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const result =
        style.perspective !== "none" ||
        (style.transformStyle === "preserve-3d" && lensOn(el.parentElement));
      lens.set(el, result);
      return result;
    };
    const own = new Map<Element, Own | null>();
    const ownOf = (el: Element): Own | null => {
      const seen = own.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const m = new DOMMatrixReadOnly(
        style.transform === "none" ? "" : style.transform,
      );
      const scale = style.scale === "none" ? [] : style.scale.split(" ");
      const sx = scale.length ? Number.parseFloat(scale[0]) : 1;
      const sy = scale.length > 1 ? Number.parseFloat(scale[1]) : sx;
      const rotate = style.rotate === "none" ? [] : style.rotate.split(" ");
      let result: Own | null = null;
      // Seen in perspective, text is drawn on a layer of its own: not ours. A
      // turn out of the plane without perspective lands flat on the screen,
      // and text under it snaps like any other.
      // A push along z alone, or a half turn, leaves it flat even under a lens.
      const inPerspective =
        Math.max(Math.abs(m.m14), Math.abs(m.m24), Math.abs(m.m34)) > 1e-9 ||
        (Math.max(
          Math.abs(m.m13),
          Math.abs(m.m31),
          Math.abs(m.m23),
          Math.abs(m.m32),
        ) > 1e-6 &&
          lensOn(el.parentElement));
      if (!inPerspective && rotate.length < 2) {
        // The `scale` property acts on what `transform` has produced.
        const lin: Lin = [m.a * sx, m.b * sy, m.c * sx, m.d * sy];
        const moved =
          style.translate === "none"
            ? 0
            : (style.translate.split(" ")[1] ?? "0px");
        const k = Math.round(lin[0]);
        const whole =
          m.is2D &&
          k >= 1 &&
          Math.abs(lin[0] - k) < 1e-4 &&
          Math.abs(lin[3] - k) < 1e-4 &&
          Math.abs(lin[1]) < 1e-5 &&
          Math.abs(lin[2]) < 1e-5 &&
          rotate.length === 0 &&
          (moved === 0 || moved.endsWith("px")) &&
          // Scaled about its corner, a box stays where layout put it.
          (k === 1 || /^0(px)? 0(px)?/.test(style.transformOrigin));
        result = {
          lin,
          turn: rotate.length ? Number.parseFloat(rotate[0]) : 0,
          carry: whole
            ? { dy: sy * m.f + (moved === 0 ? 0 : Number.parseFloat(moved)), k }
            : null,
        };
      }
      own.set(el, result);
      return result;
    };
    const down = new Map<Element, Lin | null>();
    /** Everything from the page down to and including this element. */
    const linDown = (el: Element | null): Lin | null => {
      if (!el) return LEVEL;
      const seen = down.get(el);
      if (seen !== undefined) return seen;
      const above = linDown(el.parentElement);
      const mine = above && ownOf(el);
      const result =
        above && mine
          ? times(times(above, turned(given.get(el) ?? mine.turn)), mine.lin)
          : null;
      down.set(el, result);
      return result;
    };
    const carried = new Map<Element, { dy: number; k: number } | null>();
    const carryDown = (
      el: Element | null,
    ): { dy: number; k: number } | null => {
      if (!el) return { dy: 0, k: 1 };
      const seen = carried.get(el);
      if (seen !== undefined) return seen;
      const above = carryDown(el.parentElement);
      const mine = above && !given.has(el) ? ownOf(el)?.carry : null;
      const result =
        above && mine
          ? { dy: above.dy + above.k * mine.dy, k: above.k * mine.k }
          : null;
      carried.set(el, result);
      return result;
    };
    return { ownOf, linDown, carryDown };
  }

  /**
   * Whether text in an SVG rests on the grid: it is placed wherever it is told
   * to, so only when it is shown one to one and its baseline happens to land on
   * a whole pixel. `lands` is where its own space lands on the screen.
   */
  function restsOnGrid(text: SVGTextElement, lands: DOMMatrix | null) {
    if (!lands) return false;
    const dpr = window.devicePixelRatio;
    const style = getComputedStyle(text);
    const k = lands.d * dpr;
    const y = text.y.baseVal.numberOfItems
      ? text.y.baseVal.getItem(0).value
      : 0;
    return (
      text.y.baseVal.numberOfItems <= 1 &&
      text.dy.baseVal.numberOfItems === 0 &&
      !text.querySelector("tspan[y], tspan[dy], textPath") &&
      /^(auto|alphabetic)$/.test(style.dominantBaseline) &&
      /^(auto|baseline)$/.test(style.alignmentBaseline) &&
      Math.abs(lands.b) < 1e-6 &&
      Math.abs(lands.c) < 1e-6 &&
      Math.round(k) >= 1 &&
      offWhole(k) < 2e-3 &&
      offWhole((lands.d * y + lands.f) * dpr) < ON_GRID
    );
  }

  /**
   * The angle that takes a block off the grid, given what is above it (`above`)
   * and what its own transform does (`own`), both in device pixels: the lean is
   * a turn between the two. 0 when the block leans enough as it is, null when
   * no sane angle would do.
   */
  function angleFor(above: Lin, own: Lin): number | null {
    // y from x of `above · turn(θ) · own` is p·sin θ + q·cos θ.
    const p = above[3] * own[0] - above[1] * own[1];
    const q = above[1] * own[0] + above[3] * own[1];
    if (Math.abs(q) >= LEAN) return 0;
    if (Math.abs(p) < 1e-9) return null;
    // Along the turn the scene already has, so the two never cancel out.
    const sine = ((q < 0 ? -LEAN : LEAN) - q) / p;
    if (Math.abs(sine) > Math.sin((STEEPEST * Math.PI) / 180)) return null;
    return (Math.asin(sine) * 180) / Math.PI;
  }

  function lean() {
    for (const el of leant) {
      el.style.removeProperty("rotate");
      if (el instanceof SVGElement) el.style.removeProperty("translate");
    }
    leant = [];
    const zones = document.querySelectorAll<HTMLElement | SVGElement>(MARKED);
    if (zones.length === 0) return;
    // Each block of text under a mark, and whether any transform above it moves.
    const blocks = new Map<Block, boolean>();
    // The texts a whole drawing leans for.
    const standsFor = new Map<SVGSVGElement, SVGTextElement[]>();
    for (const zone of zones) {
      const moving = zone.style.transform.includes(MOVING.trim());
      const walker = document.createTreeWalker(zone, NodeFilter.SHOW_TEXT);
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (!/\S/.test(node.nodeValue ?? "")) continue;
        const block = blockOf(node);
        // A block that turns by a property of its own is left to the scene.
        if (!block || block.style.rotate) continue;
        blocks.set(block, moving || (blocks.get(block) ?? false));
        const text = node.parentElement?.closest("text");
        if (block instanceof SVGSVGElement && text instanceof SVGTextElement)
          standsFor.set(block, [...(standsFor.get(block) ?? []), text]);
      }
      watch(zone);
    }
    for (const block of blocks.keys()) watch(block);
    const dpr = window.devicePixelRatio;
    const scaled = (m: Lin): Lin => [
      m[0] * dpr,
      m[1] * dpr,
      m[2] * dpr,
      m[3] * dpr,
    ];
    // Outer blocks first: a block inside a leaning one takes only what it
    // still lacks, so leans never pile up. Everything is read before anything
    // is written; `given` stands in for the leans not yet on the page.
    const given = new Map<Element, number>();
    const { ownOf, linDown, carryDown } = reader(given);
    const writes: (() => void)[] = [];
    const ordered = [...blocks.keys()].sort((a, b) => depthOf(a) - depthOf(b));
    for (const el of ordered) {
      const moving = blocks.get(el) === true;
      if (el instanceof HTMLElement) {
        const above = linDown(el.parentElement);
        const mine = ownOf(el);
        if (!above || !mine) continue;
        if (!moving) {
          // Layout puts a baseline on a whole pixel wherever the box itself
          // sits, so text is on the grid when the transforms around it only
          // move it by whole pixels and show it one to one (or two, or three).
          const carry = carryDown(el);
          if (
            carry &&
            offWhole(carry.k * dpr) < 2e-3 &&
            offWhole(carry.dy * dpr) < ON_GRID
          )
            continue;
        }
        const angle = angleFor(scaled(above), mine.lin);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      if (el instanceof SVGSVGElement) {
        // A whole drawing: what it does itself is its own transform and the
        // scale of its viewBox, read off where it lands on the screen.
        const above = linDown(el.parentElement);
        const lands = el.getScreenCTM();
        const det = above ? above[0] * above[3] - above[1] * above[2] : 0;
        if (!above || !lands || Math.abs(det) < 1e-12) continue;
        if (
          !moving &&
          (standsFor.get(el) ?? []).every((text) =>
            restsOnGrid(text, text.getScreenCTM()),
          )
        )
          continue;
        const mine = times(
          [above[3] / det, -above[1] / det, -above[2] / det, above[0] / det],
          [lands.a, lands.b, lands.c, lands.d],
        );
        const angle = angleFor(scaled(above), mine);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      // Its drawing leans as a whole already.
      let drawing = el.ownerSVGElement;
      while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
      if (drawing && given.has(drawing)) continue;
      // Text in an SVG is placed wherever it is told to, so it is on the grid
      // only when its baseline happens to land on a whole pixel.
      const frame = el.parentNode;
      if (!(frame instanceof SVGGraphicsElement) || el.style.translate)
        continue;
      const outer = frame.getScreenCTM();
      const whole = el.getScreenCTM();
      if (
        !outer ||
        !whole ||
        Math.abs(outer.a * outer.d - outer.b * outer.c) < 1e-12
      )
        continue;
      // What the text element itself does, in the space it is placed in.
      const mine = outer.inverse().multiply(whole);
      if (!moving && restsOnGrid(el, whole)) continue;
      const angle = angleFor(scaled([outer.a, outer.b, outer.c, outer.d]), [
        mine.a,
        mine.b,
        mine.c,
        mine.d,
      ]);
      if (!angle) continue;
      // An SVG element turns about the corner of its drawing. A move brings
      // the turn to the middle of the text instead.
      const box = el.getBBox();
      const [cx, cy] = [box.x + box.width / 2, box.y + box.height / 2];
      const [px, py] = [
        mine.a * cx + mine.c * cy + mine.e,
        mine.b * cx + mine.d * cy + mine.f,
      ];
      const [cos, sin] = [turned(angle)[0], turned(angle)[1]];
      const [tx, ty] = [px - (px * cos - py * sin), py - (px * sin + py * cos)];
      writes.push(() => {
        el.style.setProperty("rotate", `${angle}deg`);
        el.style.setProperty("translate", `${tx}px ${ty}px`);
      });
      leant.push(el);
    }
    for (const write of writes) write();
  }

  const useFrameEffect =
    typeof window === "undefined" ? useEffect : useLayoutEffect;

  function useGlide() {
    // No dependencies: the lean follows whatever this frame laid out.
    useFrameEffect(lean);
    return glide;
  }

  const glide = (moving: boolean) => (moving ? MOVING : AT_REST);

  return useGlide;
})();

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

/** gradients.sh "swirl" palette, light core to deep rim. */
const SWIRL = ["#ffe2c4", "#ff9a4d", "#d2456b", "#3a1f6b"] as const;

function mixHex(a: string, b: string, k: number) {
  const ch = (h: string, o: number) => Number.parseInt(h.slice(o, o + 2), 16);
  const m = (o: number) => Math.round(ch(a, o) + (ch(b, o) - ch(a, o)) * k);
  return `rgb(${m(1)}, ${m(3)}, ${m(5)})`;
}

interface BubbleItem {
  label: string;
  value: number;
}

interface BubblePackProps {
  items?: BubbleItem[];
  highlight?: number;
  /** Frames between bubbles as they pop in. */
  stagger?: number;
  /** Weight of the hero number. */
  fontWeight?: number;
  accent?: string;
  /** Text color of the bubble labels; overrides the theme. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the labels and hero number. Load it yourself; Bricolage Grotesque by default. */
  fontFamily?: string;
  /** Size of the bubble pack, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  theme?: "dark" | "light";
  speed?: number;
}

const DEFAULT_ITEMS: BubbleItem[] = [
  { label: "Launch videos", value: 420 },
  { label: "Demos", value: 180 },
  { label: "Changelogs", value: 150 },
  { label: "Social clips", value: 130 },
  { label: "Onboarding", value: 96 },
  { label: "Ads", value: 84 },
  { label: "Tutorials", value: 70 },
  { label: "Recaps", value: 58 },
  { label: "Teasers", value: 46 },
  { label: "Pitches", value: 38 },
];

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_GROW = Easing.bezier(0.45, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#9A999F",
    ramp: ["#3A3A40", "#222226"],
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    ramp: ["#D2D0CA", "#E7E5E0"],
    grain: 0.045,
  },
} as const;

const GROW_IN = 4;
const STAGGER = 3;
const ACC_START = 46;
const ACC_END = 86;
const SUB = 3;
const SQUASH = 2.1;

interface V {
  x: number;
  y: number;
}

function tangents(
  a: V & { r: number },
  b: V & { r: number },
  r: number,
  gap: number,
) {
  const da = a.r + r + gap;
  const db = b.r + r + gap;
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const d = Math.hypot(dx, dy);
  if (d > da + db || d < Math.abs(da - db) || d === 0) return [];
  const along = (da * da - db * db + d * d) / (2 * d);
  const h = Math.sqrt(Math.max(0, da * da - along * along));
  const mx = a.x + (dx * along) / d;
  const my = a.y + (dy * along) / d;
  return [
    { x: mx + (h * dy) / d, y: my - (h * dx) / d },
    { x: mx - (h * dy) / d, y: my + (h * dx) / d },
  ];
}

function place(placed: (V & { r: number })[], r: number, gap: number): V {
  if (placed.length === 0) return { x: 0, y: 0 };
  if (placed.length === 1)
    return { x: placed[0].x + placed[0].r + r + gap, y: 0 };
  let best: V = { x: 0, y: 0 };
  let score = Number.POSITIVE_INFINITY;
  const o = placed[0];
  for (const side of [-1, 1]) {
    const c = { x: o.x + side * (o.r + r + gap), y: o.y };
    const ok = placed.every(
      (q) => Math.hypot(q.x - c.x, q.y - c.y) >= q.r + r + gap - 0.01,
    );
    const sc = c.x * c.x + 1;
    if (ok && sc < score) {
      score = sc;
      best = c;
    }
  }
  for (let i = 0; i < placed.length; i++) {
    for (let j = i + 1; j < placed.length; j++) {
      for (const c of tangents(placed[i], placed[j], r, gap)) {
        const ok = placed.every(
          (q) => Math.hypot(q.x - c.x, q.y - c.y) >= q.r + r + gap - 0.01,
        );
        if (!ok) continue;
        const s = c.x * c.x + (c.y * SQUASH) ** 2;
        if (s < score) {
          score = s;
          best = c;
        }
      }
    }
  }
  return best;
}

function bounds(cs: (V & { r: number })[]) {
  let x0 = Number.POSITIVE_INFINITY;
  let y0 = Number.POSITIVE_INFINITY;
  let x1 = Number.NEGATIVE_INFINITY;
  let y1 = Number.NEGATIVE_INFINITY;
  for (const c of cs) {
    x0 = Math.min(x0, c.x - c.r);
    y0 = Math.min(y0, c.y - c.r);
    x1 = Math.max(x1, c.x + c.r);
    y1 = Math.max(y1, c.y + c.r);
  }
  return { cx: (x0 + x1) / 2, cy: (y0 + y1) / 2, w: x1 - x0, h: y1 - y0 };
}

function accentRadius(frame: number, seed: number, full: number) {
  const k = interpolate(frame, [ACC_START, ACC_END], [0, 1], {
    ...CLAMP,
    easing: EASE_GROW,
  });
  return seed + (full - seed) * k;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function formatValue(v: number) {
  return Math.round(v).toLocaleString("en-US");
}

function BubblePackBase({
  items = DEFAULT_ITEMS,
  highlight = 0,
  stagger = STAGGER,
  fontWeight = 500,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = sans,
  scale = 1,
  delay = 0,
  grain = true,
  theme = "dark",
  speed = 1,
}: BubblePackProps) {
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, fps } = useSceneConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const stage = background ?? p.bg;

  const model = useMemo(() => {
    const src = items.slice(0, 16).map((it, i) => ({
      ...it,
      i,
      value: Math.max(0, it.value),
    }));
    const hlIdx = Math.min(Math.max(0, Math.round(highlight)), src.length - 1);
    const vmax = Math.max(1, ...src.map((s) => s.value));
    const Rmax = 172 * u;
    const gap = 6 * u;
    const rad = (v: number) => Math.max(10 * u, Rmax * Math.sqrt(v / vmax));
    const hero = src[hlIdx];
    const grays = src
      .filter((s) => s.i !== hlIdx)
      .sort((a, b) => b.value - a.value)
      .map((s, rank) => ({ ...s, r: rad(s.value), rank }));

    const seedR = 14 * u;
    const RA = rad(hero?.value ?? vmax);
    const S: V = { x: 0, y: 0 };
    const finals: (V & { r: number })[] = [{ ...S, r: RA }];
    for (const g of grays) {
      const c = place(finals, g.r, gap);
      finals.push({ ...c, r: g.r });
    }

    const back: V[][] = [];
    const pos = finals.slice(1).map((c) => ({ x: c.x, y: c.y }));
    back.push(pos.map((q) => ({ x: q.x, y: q.y })));
    for (let f = ACC_END - 1; f >= ACC_START; f--) {
      for (let s = 0; s < SUB; s++) {
        const ff = f + 1 - (s + 1) / SUB;
        const ra = accentRadius(ff, seedR, RA);
        const pull = 0.04;
        for (const q of pos) {
          q.x += (S.x - q.x) * pull;
          q.y += (S.y - q.y) * Math.min(0.5, pull * SQUASH);
        }
        for (let it = 0; it < 5; it++) {
          for (let i = 0; i < pos.length; i++) {
            const a = pos[i];
            const ri = grays[i].r;
            let dx = a.x - S.x;
            let dy = a.y - S.y;
            let d = Math.hypot(dx, dy);
            const minA = ri + ra + gap;
            if (d < minA) {
              if (d < 1e-6) {
                dx = Math.cos(i);
                dy = Math.sin(i);
                d = 1;
              }
              const o = minA - d;
              a.x += (dx / d) * o;
              a.y += (dy / d) * o;
            }
            for (let j = i + 1; j < pos.length; j++) {
              const b = pos[j];
              const rj = grays[j].r;
              let ex = b.x - a.x;
              let ey = b.y - a.y;
              let e = Math.hypot(ex, ey);
              const min = ri + rj + gap;
              if (e >= min) continue;
              if (e < 1e-6) {
                ex = Math.cos(i + j);
                ey = Math.sin(i + j);
                e = 1;
              }
              const o = min - e;
              const wa = (rj * rj) / (ri * ri + rj * rj);
              a.x -= (ex / e) * o * wa;
              a.y -= (ey / e) * o * wa;
              b.x += (ex / e) * o * (1 - wa);
              b.y += (ey / e) * o * (1 - wa);
            }
          }
        }
      }
      back.push(pos.map((q) => ({ x: q.x, y: q.y })));
    }
    const frames = back.reverse();
    const placed = frames[0].map((q, i) => ({ ...q, r: grays[i].r }));
    const pb = bounds(placed);
    const order = placed
      .map((q, i) => ({ i, d: Math.hypot(q.x - pb.cx, (q.y - pb.cy) * 1.3) }))
      .sort((a, b) => a.d - b.d);
    const seq = new Array<number>(placed.length);
    order.forEach((o, k) => {
      seq[o.i] = k;
    });

    const availW = width * 0.84;
    const availH = height * 0.8;
    const fit = (cs: (V & { r: number })[]) => {
      const b = bounds(cs);
      return {
        cx: b.cx,
        cy: b.cy,
        s: Math.min(1.18, availW / b.w, availH / b.h),
      };
    };
    const camA = fit(placed);
    const raw = frames.map((fr, k) =>
      fit([
        ...fr.map((q, i) => ({ ...q, r: grays[i].r })),
        { ...S, r: accentRadius(ACC_START + k, seedR, RA) },
      ]),
    );
    const W = 7;
    const cams = raw.map((_, k) => {
      let cx = 0;
      let cy = 0;
      let sc = 0;
      let n = 0;
      for (let j = k - W; j <= k + W; j++) {
        const c = j < 0 ? camA : raw[Math.min(j, raw.length - 1)];
        cx += c.cx;
        cy += c.cy;
        sc += c.s;
        n++;
      }
      return { cx: cx / n, cy: cy / n, s: Math.min(sc / n, raw[k].s * 1.01) };
    });
    return { grays, hero, placed, frames, S, seedR, RA, camA, cams, seq };
  }, [items, highlight, u, width, height]);

  const { grays, hero, placed, frames, S, seedR, RA, camA, cams, seq } = model;

  const sampleAt = (i: number, tt: number) => {
    if (tt <= ACC_START) return placed[i];
    const k = Math.min(tt - ACC_START, frames.length - 1);
    const f0 = Math.floor(k);
    const f1 = Math.min(f0 + 1, frames.length - 1);
    const w = k - f0;
    return {
      x: frames[f0][i].x * (1 - w) + frames[f1][i].x * w,
      y: frames[f0][i].y * (1 - w) + frames[f1][i].y * w,
    };
  };

  const sample = (i: number) => sampleAt(i, t);

  const camFor = (tt: number) => {
    if (tt <= ACC_START) return camA;
    const k = Math.min(tt - ACC_START, cams.length - 1);
    const f0 = Math.floor(k);
    const f1 = Math.min(f0 + 1, cams.length - 1);
    const w = k - f0;
    return {
      cx: cams[f0].cx * (1 - w) + cams[f1].cx * w,
      cy: cams[f0].cy * (1 - w) + cams[f1].cy * w,
      s: cams[f0].s * (1 - w) + cams[f1].s * w,
    };
  };
  const driftAt = (tt: number) =>
    interpolate(tt, [0, ACC_END + 60], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
  const screenAt = (q: V, tt: number) => {
    const cam = camFor(tt);
    const k = cam.s * (0.985 + 0.015 * driftAt(tt));
    return {
      x: width / 2 + (q.x - cam.cx) * k,
      y: height / 2 + (q.y - cam.cy) * k,
    };
  };
  const camAt = camFor(t);
  const ccx = camAt.cx;
  const ccy = camAt.cy;
  const drift = driftAt(t);
  const cs = camAt.s * (0.985 + 0.015 * drift);
  const toScreen = (q: V) => ({
    x: width / 2 + (q.x - ccx) * cs,
    y: height / 2 + (q.y - ccy) * cs,
  });
  // Placed by `left`/`top`, the labels clicked along with the camera pixel by
  // pixel. Layout holds each where it settles for its whole life and the
  // travel is a transform, 0 once the camera is done: a label handed back to
  // layout on its last frames would snap to a whole pixel there.
  const SETTLED = ACC_END + 60;
  const shift = (
    at: (tt: number) => V,
    rest: V,
    rise: (tt: number) => number,
  ) => {
    const q = at(t);
    const moved = (ta: number, tb: number) => {
      const a = at(ta);
      const b = at(tb);
      return (
        Math.abs(a.x - b.x) > 1e-5 ||
        Math.abs(a.y + rise(ta) - b.y - rise(tb)) > 1e-5
      );
    };
    const moving = moved(t + 1, t) || moved(t, t - 1);
    return {
      left: rest.x,
      top: rest.y,
      move: `translate(${q.x - rest.x}px, ${q.y - rest.y}px) `,
      tilt: glide(moving),
    };
  };

  const ra = accentRadius(t, seedR, RA);
  const accOpacity = interpolate(
    t,
    [ACC_START - 2, ACC_START + 6],
    [0, 1],
    CLAMP,
  );
  const heroIn = interpolate(t, [ACC_END - 8, ACC_END + 14], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const heroLab = interpolate(t, [ACC_END - 2, ACC_END + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const count = interpolate(t, [ACC_END - 8, ACC_END + 22], [0.5, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.22, 1, 0.36, 1),
  });
  const quiet = interpolate(t, [ACC_START, ACC_END], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const nG = Math.max(1, grays.length - 1);
  const shade = (rank: number) => {
    const k = rank / nG;
    const a = p.ramp[0];
    const b = p.ramp[1];
    const ch = (s: string, o: number) => Number.parseInt(s.slice(o, o + 2), 16);
    const mix = (o: number) => Math.round(ch(a, o) + (ch(b, o) - ch(a, o)) * k);
    return `rgb(${mix(1)}, ${mix(3)}, ${mix(5)})`;
  };

  const gid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const sc = toScreen(S);
  const heroR = ra * cs;
  const heroFontAt = (tt: number) => {
    const cam = camFor(tt);
    const k = cam.s * (0.985 + 0.015 * driftAt(tt));
    return Math.min(136 * u, accentRadius(tt, seedR, RA) * k * 0.68);
  };
  const heroFont = Math.min(136 * u, heroR * 0.68);
  // The number's size follows the bubble until it reaches its cap. A size
  // change moves the baseline inside its own box by layout, which rounds it
  // to whole pixels, so while the size moves the number is laid out at its
  // settled size and scaled down from there; at rest it is plain text again.
  // A change under layout's 1/64px step keeps the plain path too: layout holds
  // the number still there, and those near-resting frames stay as they were.
  const heroFontRest = heroFontAt(SETTLED);
  const heroSizing =
    Math.abs(heroFontAt(t + 1) - heroFont) > 1 / 64 ||
    Math.abs(heroFont - heroFontAt(t - 1)) > 1 / 64;
  const heroK = heroFont / heroFontRest;
  // The number and its label ride their own small rises inside this box; they
  // count as its motion so its tilt covers them.
  const heroPos = shift(
    (tt) => screenAt(S, tt),
    screenAt(S, SETTLED),
    (tt) => interpolate(tt, [ACC_END - 8, ACC_END + 16], [0, 1], CLAMP) * 10,
  );

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          {grays.map((g, i) => {
            const start = GROW_IN + seq[i] * stagger;
            const k = spring({
              frame: t - start,
              fps,
              config: { damping: 15, stiffness: 120, mass: 0.7 },
            });
            const o = interpolate(t, [start, start + 6], [0, 1], CLAMP);
            const q = toScreen(sample(i));
            return (
              <circle
                key={g.label + g.i}
                cx={q.x}
                cy={q.y}
                r={Math.max(0, g.r * cs * (0.6 + 0.4 * k))}
                fill={shade(g.rank)}
                opacity={o}
              />
            );
          })}
          <defs>
            <linearGradient
              id={`${gid}h`}
              x1={0.15}
              y1={0}
              x2={0.85}
              y2={1}
              gradientTransform={`rotate(${-10 + 14 * drift} 0.5 0.5)`}
            >
              <stop offset={0} stopColor={SWIRL[0]} />
              <stop offset={0.22} stopColor={SWIRL[1]} />
              <stop offset={0.58} stopColor={SWIRL[2]} />
              <stop offset={1} stopColor={mixHex(SWIRL[3], accent, 0.25)} />
            </linearGradient>
          </defs>
          {hero ? (
            <circle
              cx={sc.x}
              cy={sc.y}
              r={heroR}
              fill={`url(#${gid}h)`}
              opacity={accOpacity}
            />
          ) : null}
        </svg>

        {grays.map((g, i) => {
          const rs = g.r * cs;
          const nameSize = 16 * u;
          const fits =
            rs >= 44 * u && g.label.length * nameSize * 0.56 <= rs * 1.6;
          if (!fits) return null;
          const start = GROW_IN + seq[i] * stagger + 8;
          const aAt = (tt: number) =>
            interpolate(tt, [start, start + 12], [0, 1], {
              ...CLAMP,
              easing: EASE_OUT,
            });
          const a = aAt(t);
          const pos = shift(
            (tt) => screenAt(sampleAt(i, tt), tt),
            screenAt(sampleAt(i, SETTLED), SETTLED),
            (tt) => (1 - aAt(tt)) * 5 * u,
          );
          return (
            <div
              key={g.label + g.i}
              style={{
                position: "absolute",
                left: pos.left,
                top: pos.top,
                transform: `${pos.move}translate(-50%, -50%) translateY(${(1 - a) * 5 * u}px)${pos.tilt}`,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: 2 * u,
                opacity: a * (1 - 0.25 * quiet),
                whiteSpace: "nowrap",
              }}
            >
              <span
                style={{
                  fontFamily,
                  fontWeight: 400,
                  fontSize: nameSize,
                  letterSpacing: "-0.01em",
                  color: fg,
                }}
              >
                {g.label}
              </span>
              <span
                style={{
                  fontFamily,
                  fontWeight: 500,
                  fontSize: 15 * u,
                  color: p.muted,
                  fontVariantNumeric: "tabular-nums",
                }}
              >
                {formatValue(g.value)}
              </span>
            </div>
          );
        })}

        {hero ? (
          <div
            style={{
              position: "absolute",
              left: heroPos.left,
              top: heroPos.top,
              transform: `${heroPos.move}translate(-50%, -50%)${heroPos.tilt}`,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              whiteSpace: "nowrap",
            }}
          >
            <span
              style={{
                fontFamily,
                fontWeight,
                fontSize: heroSizing ? heroFontRest : heroFont,
                lineHeight: 1,
                letterSpacing: "-0.04em",
                color: "#FFFFFF",
                fontVariantNumeric: "tabular-nums",
                opacity: heroIn,
                filter:
                  heroIn < 0.99
                    ? `blur(${((1 - heroIn) * 8 * u) / (heroSizing ? heroK : 1)}px)`
                    : undefined,
                // Scaled from the top, with the box pulled back to the live
                // size, so the label and the centring see the same height.
                ...(heroSizing
                  ? {
                      transform: `translateY(${(1 - heroIn) * 16 * u}px) scale(${heroK})`,
                      transformOrigin: "50% 0",
                      marginBottom: heroFont - heroFontRest,
                    }
                  : { transform: `translateY(${(1 - heroIn) * 16 * u}px)` }),
              }}
            >
              {formatValue(hero.value * count)}
            </span>
            <span
              style={{
                marginTop: 8 * u,
                fontFamily,
                fontWeight: 400,
                fontSize: 25 * u,
                letterSpacing: "-0.01em",
                color: "rgba(255,255,255,0.92)",
                opacity: heroLab,
                transform: `translateY(${(1 - heroLab) * 8 * u}px)`,
              }}
            >
              {hero.label}
            </span>
          </div>
        ) : null}
      </ScaleLayer>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 64%, ${stage} 100%)`,
          opacity: 0.5,
        }}
      />
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

